import { SwiperContainer } from "swiper/element";

// Simple interface for carousel elements
interface ICarousel extends HTMLElement {
  createCarousel?(): void;
}

// Simple interface for product data from recommendations API
interface RecommendationProduct {
  id: number;
  title: string;
  url: string;
  featured_image: string;
  price: number;
}

class ContentBlocks extends HTMLElement {
  private triggers: NodeListOf<HTMLElement> | null = null;
  private contents: NodeListOf<HTMLElement> | null = null;
  private blocksContainer: HTMLElement | null = null;
  private intersectionObserver: IntersectionObserver | null = null;

  constructor() {
    super();

    this.triggers = this.querySelectorAll("[js-content-blocks='tab-trigger']");
    this.contents = this.querySelectorAll("[js-content-blocks='tab-content']");
    this.blocksContainer = this;
  }

  connectedCallback(): void {
    this.setupTabListeners();
    this.setAriaAttributes();
    this.setupSwipers();
    this.setupDesktopNavigation();
    this.setupRecommendationsObserver();
  }

  disconnectedCallback(): void {
    if (this.intersectionObserver) {
      this.intersectionObserver.disconnect();
    }
  }

  private setupRecommendationsObserver(): void {
    // Only set up observer if we have recommendation URLs
    const hasRecommendations =
      this.dataset.block1RecUrl || this.dataset.block2RecUrl;

    if (!hasRecommendations) {
      return;
    }
    this.intersectionObserver = new IntersectionObserver(
      this.handleAsyncMethods.bind(this),
      {
        rootMargin: "0px 0px 400px 0px",
      },
    );

    this.intersectionObserver.observe(this);
  }

  private async handleAsyncMethods(
    entries: IntersectionObserverEntry[],
    observer: IntersectionObserver,
  ): Promise<void> {
    if (!entries[0].isIntersecting) return;

    observer.unobserve(this);
    await this.handleDynamicRecommendations();
  }

  /**
   * Handles dynamically fetching and setting product recommendations for each block
   * @returns Promise<void>
   */
  private async handleDynamicRecommendations(): Promise<void> {
    const promises: Promise<void>[] = [];

    // Handle block 1 recommendations
    if (this.dataset.block1RecUrl) {
      promises.push(
        this.fetchBlockRecommendations(1, this.dataset.block1RecUrl),
      );
    }

    // Handle block 2 recommendations
    if (this.dataset.block2RecUrl) {
      promises.push(
        this.fetchBlockRecommendations(2, this.dataset.block2RecUrl),
      );
    }

    try {
      await Promise.all(promises);

      // After all recommendations are loaded, check if we need to show navigation
      this.updateHeaderNavigation();
    } catch (error: unknown) {
      console.error("Error fetching recommendations:", error);
    }
  }

  /**
   * Fetches recommendations for a specific block and updates its content
   * @param blockIndex - Block number (1 or 2)
   * @param url - Recommendation URL to fetch from
   * @returns Promise<void>
   */
  private async fetchBlockRecommendations(
    blockIndex: number,
    url: string,
  ): Promise<void> {
    try {
      const response = await fetch(url);
      const contentType = response.headers.get("content-type");

      if (contentType && contentType.includes("application/json")) {
        // Handle JSON recommendations response
        const data = await response.json();

        if (data && data.products && data.products.length > 0) {
          const products = data.products as RecommendationProduct[];

          const productCards = await this.buildProductCardsFromRecommendations(
            products,
            blockIndex,
          );
          this.updateBlockContent(blockIndex, productCards);
        }
      } else {
        // Fallback to HTML handling
        const text = await response.text();

        if (text.length === 0) {
          return;
        }

        if (text.includes("404") || text.includes("Not Found")) {
          return;
        }

        const html = document.createElement("div");
        html.innerHTML = text;

        // Look for the section content
        const recommendationsSection = html.querySelector("uwp-content-blocks");

        if (!recommendationsSection) {
          return;
        }

        // Extract actual product content - look for the rendered recommendations
        const productCards =
          recommendationsSection.querySelectorAll(".product-card");

        if (productCards.length === 0) {
          return;
        }

        // Create new content structure based on number of products
        let newContent = "";

        if (productCards.length > 4) {
          // Create swiper structure
          newContent = this.createSwiperFromElements(productCards, blockIndex);
        } else {
          // Create grid structure
          newContent = this.createGridFromElements(productCards);
        }

        if (newContent) {
          this.updateBlockContent(blockIndex, newContent);
        }
      }
    } catch (error: unknown) {
      console.error(
        `Error fetching recommendations for block ${blockIndex}:`,
        error,
      );
    }
  }

  /**
   * Creates swiper HTML from existing product card elements
   * @param productCards - NodeList of existing product card elements
   * @param blockIndex - Block number for configuration
   * @returns HTML string for swiper
   */
  private createSwiperFromElements(
    productCards: NodeListOf<Element>,
    blockIndex: number,
  ): string {
    const slidesPerView = blockIndex === 1 ? "2" : "1.75";
    let slidesHtml = "";

    Array.from(productCards)
      .slice(0, 8)
      .forEach((card) => {
        slidesHtml += `
      <swiper-slide class="content-blocks__slide">
        ${card.outerHTML}
      </swiper-slide>
    `;
      });

    return `
    <swiper-container
      class="content-blocks__swiper"
      slides-per-view="${slidesPerView}"
      space-between="12"
      breakpoints='{"768": {"spaceBetween": 20, "slidesPerView": 4}}'
      role="region"
      aria-label="Product carousel ${blockIndex}"
      aria-roledescription="carousel"
    >
      ${slidesHtml}
    </swiper-container>
  `;
  }

  /**
   * Creates grid HTML from existing product card elements
   * @param productCards - NodeList of existing product card elements
   * @returns HTML string for grid
   */
  private createGridFromElements(productCards: NodeListOf<Element>): string {
    let cardsHtml = "";

    Array.from(productCards).forEach((card) => {
      cardsHtml += card.outerHTML;
    });

    return `<div class="content-blocks__grid">${cardsHtml}</div>`;
  }

  /**
   * Builds product cards HTML from JSON recommendations data
   * @param products - Array of product objects from recommendations API
   * @param blockIndex - Block number for swiper configuration
   * @returns HTML string for product cards
   */
  private async buildProductCardsFromRecommendations(
    products: RecommendationProduct[],
    blockIndex: number,
  ): Promise<string> {
    // For 5+ products, create swiper structure
    if (products.length > 4) {
      return this.createSwiperFromProducts(products, blockIndex);
    } else {
      return this.createGridFromProducts(products);
    }
  }

  /**
   * Creates swiper HTML structure from product data
   * @param products - Array of product objects
   * @param blockIndex - Block number for configuration
   * @returns HTML string for swiper
   */
  private createSwiperFromProducts(
    products: RecommendationProduct[],
    blockIndex: number,
  ): string {
    const slidesPerView = blockIndex === 1 ? "2" : "1.75";

    let slidesHtml = "";
    products.slice(0, 8).forEach((product) => {
      slidesHtml += `
        <swiper-slide class="content-blocks__slide">
          <div class="product-card">
            <a href="${product.url.split('?')[0]}" class="product-card__link">
              <div class="product-card__image">
                <img src="${product.featured_image}" alt="${product.title}" loading="lazy">
              </div>
              <div class="product-card__info">
                <h3 class="product-card__title">${product.title}</h3>
                <div class="product-card__price">${this.formatPrice(product.price)}</div>
              </div>
            </a>
          </div>
        </swiper-slide>
      `;
    });

    return `
      <swiper-container
        class="content-blocks__swiper"
        slides-per-view="${slidesPerView}"
        space-between="12"
        breakpoints='{"768": {"spaceBetween": 20, "slidesPerView": 4}}'
        role="region"
        aria-label="Product carousel ${blockIndex}"
        aria-roledescription="carousel"
      >
        ${slidesHtml}
      </swiper-container>
    `;
  }

  /**
   * Creates grid HTML structure from product data
   * @param products - Array of product objects
   * @returns HTML string for grid
   */
  private createGridFromProducts(products: RecommendationProduct[]): string {
    let cardsHtml = "";
    products.forEach((product) => {
      cardsHtml += `
        <div class="product-card">
          <a href="${product.url.split('?')[0]}" class="product-card__link">
            <div class="product-card__image">
              <img src="${product.featured_image}" alt="${product.title}" loading="lazy">
            </div>
            <div class="product-card__info">
              <h3 class="product-card__title">${product.title}</h3>
              <div class="product-card__price">${this.formatPrice(product.price)}</div>
            </div>
          </a>
        </div>
      `;
    });

    return `<div class="content-blocks__grid">${cardsHtml}</div>`;
  }

  /**
   * Formats price for display
   * @param price - Price in cents
   * @returns Formatted price string
   */
  private formatPrice(price: number): string {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(price / 100);
  }

  /**
   * Updates the content for a specific block with new HTML
   * @param blockIndex - The block number (1 or 2)
   * @param newContent - The new HTML content to insert
   */
  private updateBlockContent(blockIndex: number, newContent: string): void {
    // Find the content div for this specific tab (not the button)
    const targetTab = this.querySelector(
      `[js-content-blocks="tab-content"][data-tab="tab${blockIndex}"]`,
    );

    if (!targetTab) {
      return;
    }

    // Replace the entire tab content (grid or swiper structure)
    // This allows switching from grid (loading) to swiper (recommendations)
    targetTab.innerHTML = newContent;

    // Announce content change to screen readers
    this.announceContentChange(blockIndex);

    // Reinitialize swiper for this specific tab if it now contains a swiper
    this.reinitializeTabSwiper(targetTab);
  }

  /**
   * Updates the header navigation visibility based on whether we have swipers
   */
  private updateHeaderNavigation(): void {
    // Check if any tabs now have swipers (5+ products)
    const hasSwipers =
      this.querySelectorAll(".content-blocks__swiper, swiper-container")
        .length > 0;

    if (hasSwipers) {
      // Find the title-with-nav element
      const titleWithNav = this.querySelector(".title-with-nav");
      let navElement = this.querySelector(".title-with-nav__nav");

      if (titleWithNav && !navElement) {
        // Get section ID for navigation buttons
        const sectionId = this.id || "content-blocks";

        // Create navigation HTML structure matching swiper-nav snippet
        navElement = document.createElement("div");
        navElement.className = "swiper-nav title-with-nav__nav";

        // Create navigation that controls the active tab
        // For now, create buttons that will be dynamically connected to the active swiper
        navElement.innerHTML = `
  <button
    id="swiper-button-prev-${sectionId}"
    class="button button--icon-only button--secondary swiper-button-prev fade-on-hover"
    data-nav-action="prev"
    aria-label="Previous products"
    type="button"
  >
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path d="M15 18L9 12L15 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>
  </button>
  <button
    id="swiper-button-next-${sectionId}"
    class="button button--icon-only button--secondary swiper-button-next fade-on-hover"
    data-nav-action="next"
    aria-label="Next products"
    type="button"
  >
    <svg width="24" height="24" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path d="M9 18L15 12L9 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>
  </button>
`;

        // Append navigation to title-with-nav
        titleWithNav.appendChild(navElement);

        // Add click listeners to control the active swiper
        this.setupNavigationListeners(navElement);
      }

      if (titleWithNav && navElement) {
        // Remove hide-on-mobile class and show navigation
        navElement.classList.remove("hide-on-mobile");
        (navElement as HTMLElement).style.display = "";

        // Update any show_nav related attributes or classes
        const contentHeader = this.querySelector(".content-blocks__header");
        if (contentHeader) {
          contentHeader.setAttribute("data-show-nav", "true");
        }
      }
    }
  }

  /**
   * Sets up click listeners for navigation buttons to control active swiper
   * @param navElement - The navigation element containing the buttons
   */
  private setupNavigationListeners(navElement: Element): void {
    const prevButton = navElement.querySelector('[data-nav-action="prev"]');
    const nextButton = navElement.querySelector('[data-nav-action="next"]');

    if (prevButton) {
      prevButton.addEventListener("click", () => {
        this.navigateActiveSwiper("prev");
      });

      // Add keyboard support
      prevButton.addEventListener("keydown", (e) => {
        const keyEvent = e as KeyboardEvent;
        if (keyEvent.key === "Enter" || keyEvent.key === " ") {
          keyEvent.preventDefault();
          this.navigateActiveSwiper("prev");
        }
      });
    }

    if (nextButton) {
      nextButton.addEventListener("click", () => {
        this.navigateActiveSwiper("next");
      });

      // Add keyboard support
      nextButton.addEventListener("keydown", (e) => {
        const keyEvent = e as KeyboardEvent;
        if (keyEvent.key === "Enter" || keyEvent.key === " ") {
          keyEvent.preventDefault();
          this.navigateActiveSwiper("next");
        }
      });
    }
  }

  /**
   * Navigates the currently active swiper
   * @param direction - Direction to navigate ('prev' or 'next')
   */
  private navigateActiveSwiper(direction: "prev" | "next"): void {
    // Find the active tab
    const activeTab = this.querySelector(".content-blocks__tab.is-active");
    if (!activeTab) {
      return;
    }

    // Find swiper in the active tab
    const swiperEl = activeTab.querySelector(
      "swiper-container",
    ) as SwiperContainer;
    if (!swiperEl || !swiperEl.swiper) {
      return;
    }

    // Navigate the swiper
    if (direction === "prev") {
      swiperEl.swiper.slidePrev();
    } else {
      swiperEl.swiper.slideNext();
    }
  }

  private reinitializeTabSwiper(tabElement: Element): void {
    // Match your ProductCarousel pattern exactly
    const carousel = tabElement.querySelector(
      "uwp-carousel",
    ) as null | ICarousel;

    if (!carousel) {
      // Fallback to swiper-container if uwp-carousel not found
      const swiperContainer = tabElement.querySelector(
        "swiper-container",
      ) as SwiperContainer;
      if (swiperContainer) {
        this.setupSwiperForElement(swiperContainer);
      }
      return;
    }

    // Use your exact ProductCarousel reinit pattern
    if (carousel.createCarousel) {
      carousel.createCarousel();
    }
  }

  /**
   * Sets up swiper for a specific element
   * @param swiperEl - The swiper container element
   */
  private setupSwiperForElement(swiperEl: SwiperContainer): void {
    const setupSwiperEvents = () => {
      this.setupSwiperNavigation(swiperEl);
    };

    // Wait for swiper to be ready
    swiperEl.addEventListener("swiperinit", setupSwiperEvents);

    // If swiper is already initialized
    if (swiperEl.swiper) {
      setupSwiperEvents();
    }
  }

  private setupTabListeners(): void {
    this.triggers?.forEach((trigger, index) => {
      trigger.addEventListener("click", this.handleTriggerClick.bind(this));
      trigger.addEventListener("keydown", (e) => this.handleKeyDown(e, index));
    });
  }

  private setAriaAttributes(): void {
    // Set role for tabs container
    const tabsContainer = this.querySelector(".title-with-nav__tabs");
    if (tabsContainer) {
      tabsContainer.setAttribute("role", "tablist");
    }

    this.triggers?.forEach((trigger, index) => {
      const tabId = `content-blocks-tab-${index}`;
      const panelId = `content-blocks-panel-${index}`;

      // Tab button attributes
      trigger.setAttribute("role", "tab");
      trigger.setAttribute("id", tabId);
      trigger.setAttribute("aria-controls", panelId);
      this.updateTabAriaState(trigger, trigger.classList.contains("is-active"));

      // Tab panel attributes
      const content = this.contents?.[index];
      if (content) {
        content.setAttribute("role", "tabpanel");
        content.setAttribute("id", panelId);
        content.setAttribute("aria-labelledby", tabId);
        content.setAttribute("tabindex", "0");
        content.setAttribute(
          "aria-hidden",
          (!content.classList.contains("is-active")).toString(),
        );
      }
    });
  }

  private updateTabAriaState(trigger: HTMLElement, isActive: boolean): void {
    trigger.setAttribute("aria-selected", isActive.toString());
    trigger.setAttribute("tabindex", isActive ? "0" : "-1");
  }

  private announceTabChange(tabName: string): void {
    // Create or update live region for screen reader announcements
    let announcer = document.getElementById("content-blocks-announcer");
    if (!announcer) {
      announcer = document.createElement("div");
      announcer.id = "content-blocks-announcer";
      announcer.setAttribute("aria-live", "polite");
      announcer.setAttribute("aria-atomic", "true");
      announcer.className = "sr-only";
      announcer.style.cssText = `
        position: absolute !important;
        width: 1px !important;
        height: 1px !important;
        padding: 0 !important;
        margin: -1px !important;
        overflow: hidden !important;
        clip: rect(0, 0, 0, 0) !important;
        white-space: nowrap !important;
        border: 0 !important;
      `;
      document.body.appendChild(announcer);
    }

    announcer.textContent = `Switched to ${tabName} tab`;
  }

  private announceContentChange(blockIndex: number): void {
    let announcer = document.getElementById("content-blocks-announcer");
    if (!announcer) {
      announcer = document.createElement("div");
      announcer.id = "content-blocks-announcer";
      announcer.setAttribute("aria-live", "polite");
      announcer.setAttribute("aria-atomic", "true");
      announcer.className = "sr-only";
      announcer.style.cssText = `
        position: absolute !important;
        width: 1px !important;
        height: 1px !important;
        padding: 0 !important;
        margin: -1px !important;
        overflow: hidden !important;
        clip: rect(0, 0, 0, 0) !important;
        white-space: nowrap !important;
        border: 0 !important;
      `;
      document.body.appendChild(announcer);
    }

    announcer.textContent = `Recommendations loaded for block ${blockIndex}`;
  }

  private setupSwipers(): void {
    const swipers = this.querySelectorAll("swiper-container");

    swipers.forEach((swiperEl) => {
      this.setupSwiperForElement(swiperEl as SwiperContainer);
    });
  }

  private setupSwiperNavigation(swiperEl: SwiperContainer): void {
    if (!swiperEl.swiper) {
      return;
    }

    // Get the tab container to scope navigation buttons
    const tabContainer = swiperEl.closest("[data-tab]");
    const tabId = tabContainer?.getAttribute("data-tab") || "unknown";
    const sectionIdFromAttribute =
      this.getAttribute("data-section-id") || this.id;

    const { nextButton, prevButton } = this.findNavigationButtons(
      sectionIdFromAttribute,
      tabId,
      tabContainer,
      swiperEl,
    );

    this.attachNavigationListeners(nextButton, prevButton, swiperEl);
  }

  private findNavigationButtons(
    sectionId: string | null,
    tabId: string,
    tabContainer: Element | null,
    swiperEl: Element,
  ): { nextButton: Element | null; prevButton: Element | null } {
    let nextButton: Element | null = null;
    let prevButton: Element | null = null;

    // Method 1: Try the expected selectors with section ID
    if (sectionId) {
      nextButton = this.querySelector(
        `#swiper-button-next-${sectionId}-${tabId}`,
      );
      prevButton = this.querySelector(
        `#swiper-button-prev-${sectionId}-${tabId}`,
      );
    }

    // Method 2: Try with component ID if section ID failed
    if ((!nextButton || !prevButton) && this.id) {
      nextButton =
        nextButton ||
        this.querySelector(`#swiper-button-next-${this.id}-${tabId}`);
      prevButton =
        prevButton ||
        this.querySelector(`#swiper-button-prev-${this.id}-${tabId}`);
    }

    // Method 3: Look within the tab container
    if (!nextButton || !prevButton) {
      nextButton =
        nextButton ||
        (tabContainer?.querySelector(".swiper-button-next") ?? null);
      prevButton =
        prevButton ||
        (tabContainer?.querySelector(".swiper-button-prev") ?? null);
    }

    // Method 4: Look for any buttons near this swiper
    if (!nextButton || !prevButton) {
      const swiperContainer = swiperEl.closest(".content-blocks__tab");
      nextButton =
        nextButton ||
        (swiperContainer?.querySelector(".swiper-button-next") ?? null);
      prevButton =
        prevButton ||
        (swiperContainer?.querySelector(".swiper-button-prev") ?? null);
    }

    return { nextButton, prevButton };
  }

  private attachNavigationListeners(
    nextButton: Element | null,
    prevButton: Element | null,
    swiperEl: SwiperContainer,
  ): void {
    if (nextButton) {
      nextButton.addEventListener("click", (e: Event) => {
        e.preventDefault();
        e.stopPropagation();
        swiperEl.swiper.slideNext();
      });
    }

    if (prevButton) {
      prevButton.addEventListener("click", (e: Event) => {
        e.preventDefault();
        e.stopPropagation();
        swiperEl.swiper.slidePrev();
      });
    }
  }

  private setupDesktopNavigation(): void {
    const allButtons = document.querySelectorAll('[id*="swiper-button"]');

    // Find desktop navigation buttons (class-based approach first)
    let desktopNextButton =
      this.querySelector(".hide-on-mobile .swiper-button-next") ||
      this.querySelector(".title-with-nav .swiper-button-next");
    let desktopPrevButton =
      this.querySelector(".hide-on-mobile .swiper-button-prev") ||
      this.querySelector(".title-with-nav .swiper-button-prev");

    // Fallback: ID-based approach for desktop buttons (no tab suffix)
    if (!desktopNextButton || !desktopPrevButton) {
      const desktopButtonIds = Array.from(allButtons)
        .map((btn: Element) => btn.id)
        .filter(
          (id: string) =>
            id.includes("swiper-button") &&
            !id.includes("-tab1") &&
            !id.includes("-tab2"),
        );

      for (const buttonId of desktopButtonIds) {
        if (buttonId.includes("next") && !desktopNextButton) {
          desktopNextButton = document.getElementById(buttonId);
        }
        if (buttonId.includes("prev") && !desktopPrevButton) {
          desktopPrevButton = document.getElementById(buttonId);
        }
      }
    }

    this.attachDesktopNavigationListeners(desktopNextButton, desktopPrevButton);
  }

  private attachDesktopNavigationListeners(
    nextButton: Element | null,
    prevButton: Element | null,
  ): void {
    const slideNext = () => {
      const activeTab = this.querySelector(".content-blocks__tab.is-active");
      const activeSwiper = activeTab?.querySelector(
        "swiper-container",
      ) as SwiperContainer;
      activeSwiper?.swiper?.slideNext();
    };

    const slidePrev = () => {
      const activeTab = this.querySelector(".content-blocks__tab.is-active");
      const activeSwiper = activeTab?.querySelector(
        "swiper-container",
      ) as SwiperContainer;
      activeSwiper?.swiper?.slidePrev();
    };

    if (nextButton) {
      nextButton.addEventListener("click", (e: Event) => {
        e.preventDefault();
        e.stopPropagation();
        slideNext();
      });
    }

    if (prevButton) {
      prevButton.addEventListener("click", (e: Event) => {
        e.preventDefault();
        e.stopPropagation();
        slidePrev();
      });
    }
  }

  private handleTriggerClick(event: Event): void {
    const target = event.target as HTMLElement;
    const tab = target.getAttribute("data-tab");
    const colourScheme = target.getAttribute("data-colour-scheme");

    if (!tab || target.classList.contains("is-active")) {
      return;
    }

    // Update tab states
    this.triggers?.forEach((trigger) => {
      const isActive = trigger === target;
      trigger.classList.toggle("is-active", isActive);
      this.updateTabAriaState(trigger, isActive);
    });

    // Update content states
    this.contents?.forEach((content) => {
      const isActive = content.getAttribute("data-tab") === tab;
      content.classList.toggle("is-active", isActive);
      content.setAttribute("aria-hidden", (!isActive).toString());
    });

    // Update colour scheme
    this.updateColourScheme(colourScheme);

    // Announce change to screen readers
    const tabLabel = target.textContent?.trim() || tab;
    this.announceTabChange(tabLabel);

    // Focus management - move focus to the newly active tab panel
    const activeContent = this.querySelector(`[data-tab="${tab}"]`);
    if (activeContent instanceof HTMLElement) {
      activeContent.focus();
    }

    // Dispatch custom event
    this.dispatchEvent(
      new CustomEvent("contentBlocksTabChanged", {
        detail: {
          activeTab: tab,
          colourScheme: colourScheme,
          tabElement: target,
          contentElement: activeContent,
        },
        bubbles: true,
      }),
    );
  }

  private updateColourScheme(colourScheme: string | null): void {
    if (!this.blocksContainer || !colourScheme) return;

    // Remove all classes matching colour-scheme--
    this.blocksContainer.classList.forEach((cls) => {
      if (cls.startsWith("colour-scheme--")) {
        this.blocksContainer?.classList.remove(cls);
      }
    });

    // Add new colour scheme class
    this.blocksContainer.classList.add(`colour-scheme--${colourScheme}`);
  }

  private handleKeyDown(event: KeyboardEvent, currentIndex: number): void {
    if (!this.triggers) return;

    let targetIndex = currentIndex;

    switch (event.key) {
      case "ArrowLeft":
        event.preventDefault();
        targetIndex =
          currentIndex > 0 ? currentIndex - 1 : this.triggers.length - 1;
        break;
      case "ArrowRight":
        event.preventDefault();
        targetIndex =
          currentIndex < this.triggers.length - 1 ? currentIndex + 1 : 0;
        break;
      case "Home":
        event.preventDefault();
        targetIndex = 0;
        break;
      case "End":
        event.preventDefault();
        targetIndex = this.triggers.length - 1;
        break;
      case "Enter":
      case " ":
        event.preventDefault();
        (this.triggers[currentIndex] as HTMLElement).click();
        return;
      default:
        return;
    }

    // Focus and activate the target tab
    const targetTrigger = this.triggers[targetIndex] as HTMLElement;
    targetTrigger.focus();
    targetTrigger.click();
  }

  // Public API methods
  public setActiveTab(index: number): void {
    if (this.triggers && index >= 0 && index < this.triggers.length) {
      (this.triggers[index] as HTMLElement).click();
    }
  }

  public getActiveTabIndex(): number {
    if (!this.triggers) return -1;

    return Array.from(this.triggers).findIndex((trigger) =>
      trigger.classList.contains("is-active"),
    );
  }

  public getActiveTabId(): string | null {
    const activeIndex = this.getActiveTabIndex();
    if (activeIndex === -1 || !this.triggers) return null;

    return this.triggers[activeIndex].getAttribute("data-tab");
  }

  public getActiveColourScheme(): string | null {
    const activeIndex = this.getActiveTabIndex();
    if (activeIndex === -1 || !this.triggers) return null;

    return this.triggers[activeIndex].getAttribute("data-colour-scheme");
  }

  /**
   * Public method to manually trigger recommendation fetching
   * @returns Promise<void>
   */
  public async fetchRecommendations(): Promise<void> {
    await this.handleDynamicRecommendations();
  }
}

customElements.define("uwp-content-blocks", ContentBlocks);

export { ContentBlocks };
